insert into public.history_event_sources (event_id,source_id,is_primary,evidence_role,supports_claim,confidence_note,citation_locator) values ('timbuktu_scholarly_centres','src_unesco_timbuktu',FALSE,'archaeological_record','المراكز التاريخية والعمرانية في تمبكتو','مصدر مؤسسي للموقع.','Description / History') on conflict do nothing;
insert into public.history_event_sources (event_id,source_id,is_primary,evidence_role,supports_claim,confidence_note,citation_locator) values ('uruk_early_writing','src_met_mesopotamia',FALSE,'scholarly_analysis','ارتباط الكتابة المسمارية المبكرة بالإدارة وتسجيل السلع','مرجع بحثي تمهيدي.','Heilbrunn Timeline: Writing') on conflict do nothing;
insert into public.history_event_sources (event_id,source_id,is_primary,evidence_role,supports_claim,confidence_note,citation_locator) values ('uruk_early_writing','src_uruk_penn',FALSE,'archaeological_record','سياق أوروك الأثري وتطور الكتابة المبكرة','بوابة مؤسسية؛ يفضل لاحقًا ربط رقم قطعة محدد.','المواد التعريفية والأثرية عن أوروك والكتابة المبكرة') on conflict do nothing;
insert into public.history_comparisons (id,status,title_ar,title_en,context_ar,created_at,updated_at,period_label,limitations_ar,method_version,civilization_a_id,civilization_b_id) values ('abbasid_tang','published','العصر العباسي × سلالة تانغ',NULL,'مراكز سياسية واسعة في أوراسيا تزامنت مع التجارة البرية والبحرية وتبادل التقنيات والأديان والمعارف، لكنها امتلكت نظمًا سياسية ولغوية وإدارية مختلفة.','2026-11-13T20:27:34.83663+00:00','2026-11-13T20:27:34.83663+00:00','القرنان 8–9م','لا تختزل العصر العباسي في بغداد وحدها ولا تانغ في تشانغآن وحدها. المعرفة نتاج شبكات ومؤسسات وأفراد، لا معجزة حضارية منعزلة.','1.0','abbasid','tang') on conflict do nothing;
insert into public.history_comparisons (id,status,title_ar,title_en,context_ar,created_at,updated_at,period_label,limitations_ar,method_version,civilization_a_id,civilization_b_id) values ('aksum_mali','published','أكسوم × إمبراطورية مالي',NULL,'قوتان أفريقيتان ارتبطتا بشبكات تجارة عابرة للأقاليم؛ أكسوم حول القرن الأفريقي والبحر الأحمر، ومالي في غرب أفريقيا وطرق الذهب والملح وحوض النيجر.','2026-11-13T20:27:34.83663+00:00','2026-11-13T20:27:34.83663+00:00','نحو القرن 1–7م / القرن 13–16م','الفاصل الزمني كبير، ومصادر أكسوم النقشية والأثرية تختلف عن مصادر مالي المكتوبة غالبًا من خارجها أو من عصور لاحقة.','1.0','aksum','mali') on conflict do nothing;
insert into public.history_comparisons (id,status,title_ar,title_en,context_ar,created_at,updated_at,period_label,limitations_ar,method_version,civilization_a_id,civilization_b_id) values ('han_rome','published','إمبراطورية هان × روما',NULL,'إمبراطوريتان واسعتان في أوراسيا امتلكتا أجهزة إدارية وضرائب وجيوشًا وطرقًا وأسواقًا، لكنهما اختلفتا في القانون ومصادر الشرعية والعلاقة بين المركز والأقاليم.','2026-11-13T20:27:34.83663+00:00','2026-11-13T20:27:34.83663+00:00','206 ق.م–220م / 27 ق.م–476م للغرب الروماني','الفترتان لا تتطابقان: انتهت هان عام 220م بينما استمرت الإمبراطورية الرومانية قرونًا أخرى. لا تساوِ بين مفاهيم المواطنة والبيروقراطية في السياقين.','1.0','han_dynasty','roman_empire') on conflict do nothing;
insert into public.history_comparisons (id,status,title_ar,title_en,context_ar,created_at,updated_at,period_label,limitations_ar,method_version,civilization_a_id,civilization_b_id) values ('maya_inca','published','ممالك المايا × دولة الإنكا',NULL,'تجربتان أمريكيتان قبل الغزو الأوروبي: شبكة ممالك مدينية في أمريكا الوسطى ودولة توسعية ذات طرق ومخازن في جبال الأنديز.','2026-11-13T20:27:34.83663+00:00','2026-11-13T20:27:34.83663+00:00','القرون 3–16م مع اختلاف المسارات الإقليمية','المايا ليست إمبراطورية واحدة، وحضارتها أقدم وأطول من الحقبة الكلاسيكية. توسعت الإنكا بسرعة في القرن 15، وتأثرت المصادر المكتوبة عنها بالتدوين الاستعماري.','1.0','maya','inca') on conflict do nothing;
insert into public.history_comparisons (id,status,title_ar,title_en,context_ar,created_at,updated_at,period_label,limitations_ar,method_version,civilization_a_id,civilization_b_id) values ('mesopotamia_egypt','published','بلاد الرافدين × مصر القديمة',NULL,'حالتان مبكرتان لتشكل المدن والدولة في بيئات نهرية، لكنهما ليستا نموذجين ثابتين ولا متزامنين في كل مراحلهما.','2026-11-13T20:27:34.83663+00:00','2026-11-13T20:27:34.83663+00:00','الألفية الرابعة–الثانية ق.م','لا تختزل المقارنة في مدن متنافسة مقابل دولة موحدة: شهدت مصر تجزؤًا، وشهدت بلاد الرافدين إمبراطوريات وممالك واسعة. تختلف كثافة النصوص وفترات حفظها.','1.0','mesopotamian','ancient_egypt') on conflict do nothing;
insert into public.history_comparison_dimensions (id,label_ar,label_en,sort_order,description_ar) values ('political_power','السلطة السياسية','Political power',1,'مصادر الشرعية، بنية الحكم، التنافس، الخلافة، وحدود السيطرة.') on conflict do nothing;
insert into public.history_comparison_dimensions (id,label_ar,label_en,sort_order,description_ar) values ('institutions','الإدارة والمؤسسات','Administration and institutions',2,'البيروقراطية والقانون والضرائب والجيش والإدارة المحلية.') on conflict do nothing;
insert into public.history_comparison_dimensions (id,label_ar,label_en,sort_order,description_ar) values ('economy','الاقتصاد والموارد','Economy and resources',3,'الإنتاج والعمل والضرائب والأسواق والنقد والموارد.') on conflict do nothing;
insert into public.history_comparison_dimensions (id,label_ar,label_en,sort_order,description_ar) values ('society','المجتمع والعمل','Society and labor',4,'الفئات الاجتماعية والعمل والمدينة والريف والنوع الاجتماعي.') on conflict do nothing;
insert into public.history_comparison_dimensions (id,label_ar,label_en,sort_order,description_ar) values ('environment','البيئة والجغرافيا','Environment and geography',5,'المناخ والأنهار والتضاريس والموارد وكلفة النقل.') on conflict do nothing;
insert into public.history_comparison_dimensions (id,label_ar,label_en,sort_order,description_ar) values ('knowledge','المعرفة والتقنية','Knowledge and technology',6,'التعليم والكتابة والعلوم والتقنيات وطرق انتقالها.') on conflict do nothing;
insert into public.history_comparison_dimensions (id,label_ar,label_en,sort_order,description_ar) values ('networks','شبكات الاتصال','Networks and exchange',7,'التجارة والهجرة والدبلوماسية والدين وانتقال السلع والأفكار.') on conflict do nothing;
insert into public.history_comparison_dimensions (id,label_ar,label_en,sort_order,description_ar) values ('evidence','الأدلة والمصادر','Evidence and sources',8,'نوعية الأدلة وبقاؤها وتحيزات التدوين وحدود التأريخ.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('am_economy',ARRAY[],'economy','aksum_mali',NULL,'السلع العابرة لا تعني أن السكان شاركوا بالتساوي في الثروة.','تجارة البحر الأحمر والذهب والعاج والسلع مع سك عملة.','ذهب وملح وقوافل وزراعة نهرية ومدن تجارية.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('am_environment',ARRAY[],'environment','aksum_mali',NULL,'الجغرافيا شكلت كلفة النقل ومسارات الاتصال لا مصيرًا محتومًا.','مرتفعات وموانئ وسواحل تربط أفريقيا بالجزيرة العربية والمتوسط.','الساحل والسافانا والنيجر والصحراء الكبرى.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('am_evidence',ARRAY[],'evidence','aksum_mali',NULL,'تُقرأ روايات الرحالة ضمن غرضها وسياقها وتاريخ تدوينها.','عملات ونقوش ومسلات وعمارة ومصادر خارجية.','مصادر عربية ورحلات ومخطوطات وآثار وروايات شفوية.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('am_institutions',ARRAY[],'institutions','aksum_mali',NULL,'الأدلة المتاحة لا تسمح بقياس الإدارة بمقياس موحد.','نقوش وعملات ومؤسسات ملكية ومراكز تجارية.','حكام وأقاليم ومدن تجارية وشبكات علماء وتجار.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('am_knowledge',ARRAY[],'knowledge','aksum_mali',NULL,'غياب النص المكتوب لا يعني غياب المعرفة بل يغير ما يمكن إثباته.','كتابات متعددة وعملات ونقوش وشواهد معمارية.','مخطوطات عربية ومراكز علم وتقاليد شفوية.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('am_networks',ARRAY[],'networks','aksum_mali',NULL,'الشبكات تتغير مع الأمن والسلع والبيئة والتحولات السياسية.','البحر الأحمر والمحيط الهندي وصلات الجزيرة العربية والمتوسط.','طرق الصحراء ومصر والمغرب وشبكات الحج والعلم.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('am_political',ARRAY[],'political_power','aksum_mali',NULL,'الألقاب الملكية لا تكشف وحدها مدى السيطرة الفعلية على الأطراف.','ملكية في المرتفعات الإثيوبية ومراكز ساحلية متصلة بالبحر الأحمر.','إمبراطورية متعددة الأقاليم تفاوت نفوذها بحسب الحكام والطرق والمدن.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('am_society',ARRAY[],'society','aksum_mali',NULL,'تجنب إسقاط وصف واحد على مجتمعات واسعة ومتنوعة.','مجتمعات متنوعة في المرتفعات والموانئ ومراكز الحكم.','مجتمعات متعددة في الساحل والسافانا وحوض النيجر.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('at_economy',ARRAY[],'economy','abbasid_tang',NULL,'طريق الحرير شبكة متعددة المسارات لا طريقًا واحدًا ثابتًا؛ تختلف كثافة التجارة باختلاف الأمن والسياسة.','أسواق ومدن وموانئ وشبكات نقد وتجارة برية وبحرية تربط المتوسط والمحيط الهندي.','أسواق حضرية وزراعة ونقد وتجارة برية وبحرية تربط آسيا الوسطى وشرق آسيا.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('at_environment',ARRAY[],'environment','abbasid_tang',NULL,'تتعدد البيئات داخل الإمبراطوريات ولا يجوز تعميم خصائص العاصمة على كل الإقليم.','تباين بيئات الأقاليم من العراق الزراعي إلى الشام وإيران ومصر وآسيا الوسطى.','تباين بيئات السهول والأنهار والمرتفعات والسواحل في شرق آسيا وآسيا الداخلية.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('at_evidence',ARRAY[],'evidence','abbasid_tang',NULL,'كل تقليد تدويني له انتقاءاته ومصالحه ويحتاج مضاهاة.','مصادر عربية وفارسية ومخطوطات وسجلات نقدية وآثار.','تواريخ سلالية ونقوش ووثائق ومجموعات أثرية ومصادر خارجية.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('at_institutions',ARRAY[],'institutions','abbasid_tang',NULL,'قارن وظائف الإدارة وآليات اختيار الموظفين لا أسماء المؤسسات فقط.','دواوين وولاة وجباية وإدارة عسكرية ومالية تتغير عبر مراحل الدولة العباسية.','وزارات ومجالس وولاة محليون ونظام امتحانات الخدمة المدنية تطور عبر تاريخ تانغ.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('at_knowledge',ARRAY[],'knowledge','abbasid_tang',NULL,'تتبع مسارات النصوص والمترجمين والرعاة ولا تنسب المعرفة إلى هوية حضارية واحدة.','ترجمة ونسخ وتأليف في الفلسفة والطب والرياضيات والفلك بمشاركة لغات ومؤسسات متعددة.','تقاليد تدوين تاريخي وفنون وتقنيات واتصال بالبوذية وشبكات معرفية إقليمية.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('at_networks',ARRAY[],'networks','abbasid_tang',NULL,'الاتصال لا يعني وحدة ثقافية أو سيطرة سياسية مشتركة.','شبكات حج وتجارة وعلم تربط أفريقيا وآسيا والمتوسط.','تجارة برية وبحرية تربط آسيا الوسطى وشرق آسيا والمحيط الهندي.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('at_political',ARRAY[],'political_power','abbasid_tang',NULL,'الألقاب السياسية لا تعكس وحدها السيطرة الفعلية على الأقاليم.','خلافة متعددة الأقاليم؛ تفاوت نفوذ الخليفة والولاة والقوى المحلية عبر الزمن.','ملكية سلالية ذات بيروقراطية إمبراطورية؛ تفاوت السيطرة المركزية بحسب الأقاليم والفترات.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('at_society',ARRAY[],'society','abbasid_tang',NULL,'لا تصف أي إمبراطورية بأنها متسامحة أو مغلقة طوال تاريخها؛ حلل السياسة في سياقها.','تعدد ديني ومذهبي ولغوي ومجتمعات مدينية وريفية؛ تغيرت سياسات الرعاية والضرائب.','تعايش بوذي وداوي وكونفوشي ومجتمعات وافدة، مع سياسات دينية متباينة عبر العهود.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('hr_economy',ARRAY[],'economy','han_rome',NULL,'تختلف بنية الجباية والأسواق بين الأقاليم والفترات؛ لا تقارن حجم التجارة من دون مراعاة اختلاف الأدلة.','اقتصاد زراعي واسع، مع تدخل الدولة في بعض الموارد والاحتكارات والضرائب، وتجارة برية تربط آسيا الوسطى.','اقتصاد متوسطي زراعي وتجاري، وضرائب نقدية وعينية وشبكات موانئ وطرق.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('hr_environment',ARRAY[],'environment','han_rome',NULL,'الجغرافيا الإمبراطورية متعددة الأقاليم ولا تختزل في نهر أو بحر واحد.','سهول الأنهار الشمالية ومناطق زراعية متنوعة وحدود بيئية ومناخية واسعة.','حوض المتوسط وأقاليم أوروبية وآسيوية وأفريقية تتفاوت في المناخ والموارد وكلفة النقل.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('hr_evidence',ARRAY[],'evidence','han_rome',NULL,'تقاليد تدوين التاريخ ارتبطت بمصالح البلاط والنخب وتقرأ نقديًا.','سجلات تاريخية ونقوش ومقابر ووثائق خشبية وحريرية.','نقوش وعملات ونصوص قانونية ومؤرخون وآثار.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('hr_institutions',ARRAY[],'institutions','han_rome',NULL,'لا تعني البيروقراطية الصينية مركزية مطلقة ولا غياب الإدارة في روما.','بيروقراطية مدنية وكتابية مع تفاوت قدرة الدولة على الوصول للأقاليم.','حكام أقاليم وموظفون وجباية وجيش مع تنوع في الإدارة المحلية.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('hr_knowledge',ARRAY[],'knowledge','han_rome',NULL,'ميّز بين الاختراع والتوثيق والانتشار والاستخدام الاجتماعي؛ لا توجد وحدة قياس واحدة للتقدم.','تقاليد الكتابة التاريخية والفلكية وتقنيات الحديد والورق المبكر والإدارة الكتابية.','هندسة الطرق والمياه والعمارة والقانون والتقنيات العسكرية والملاحية.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('hr_networks',ARRAY[],'networks','han_rome',NULL,'الحدود مناطق اتصال وتفاوض وتجارة وليست خطوطًا مغلقة دائمًا.','طرق برية وحدود شمالية وروابط مع آسيا الوسطى.','موانئ وطرق برية وحدود أوروبية وآسيوية وأفريقية.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('hr_political',ARRAY[],'political_power','han_rome',NULL,'الشرعية تفاوضت عليها النخب والأقاليم والجيوش.','سلالة إمبراطورية تستند إلى شرعية سلالية وفكرة التفويض السماوي.','إمبراطور يجمع السلطة العسكرية والسياسية مع استمرار ألقاب ومؤسسات جمهورية.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('hr_society',ARRAY[],'society','han_rome',NULL,'لا تختزل المجتمع في العاصمة أو النخبة، وتختلف فئات السكان القانونية والاجتماعية بين السياقين.','مجتمعات ريفية واسعة ومدن إدارية وأسواق ونخب محلية؛ تفاوت اجتماعي وقانوني واضح.','مجتمعات مدينية وريفية متعددة، وعبيد ومحررون ومواطنون ونخب محلية ضمن أوضاع قانونية متباينة.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('me_economy',ARRAY[],'economy','mesopotamia_egypt',NULL,'البيئة تضع شروطًا وفرصًا، لكنها لا تفسر وحدها شكل الدولة.','زراعة مروية وشبكات قنوات تتطلب صيانة وتنسيقًا محليًا وإقليميًا.','ارتبط الاستقرار بفيضان النيل وأعمال ري وإدارة متعددة المستويات.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('me_environment',ARRAY[],'environment','mesopotamia_egypt',NULL,'لكل منطقة فروق مناخية واجتماعية؛ لا تختزل الجغرافيا إلى نهر واحد.','سهول فيضية ومجاري متغيرة ومناطق زراعية تعتمد على القنوات.','وادي نهري طويل وصحراء تحيط بمناطق الاستقرار.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('me_evidence',ARRAY[],'evidence','mesopotamia_egypt',NULL,'تتفاوت كثافة النصوص وفترات حفظها؛ بعض الفترات أقل توثيقًا.','ألواح مسمارية وآثار مدن وأختام ومدافن ونصوص قانونية.','برديات ونقوش ومقابر ومبانٍ ومصادر خارجية.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('me_institutions',ARRAY[],'institutions','mesopotamia_egypt',NULL,'نوع النصوص الباقية لا يمثل كل المجتمع ولا كل وظائف الكتابة.','كتابة مسمارية ارتبطت بالحساب والمخازن والمعاملات ثم توسعت وظائفها.','هيروغليفية ونظم كتابية أخرى للإدارة والطقوس والنقوش الملكية.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('me_knowledge',ARRAY[],'knowledge','mesopotamia_egypt',NULL,'قارن المشكلات التي سعت المؤسسات لحلها، لا ترتيب الأذكى.','رياضيات حسابية وفلك وتقنيات طين ومعادن ونقل.','هندسة وطب وتقويم ورصد وتقنيات حجرية ونقل نهري.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('me_networks',ARRAY[],'networks','mesopotamia_egypt',NULL,'الحدود الثقافية كانت مسامية والتبادل شمل السلع والأفكار والأفراد.','الخليج وإيران والأناضول والشام وشبكات الأنهار.','النوبة وشرق المتوسط والبحر الأحمر والصحراء.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('me_political',ARRAY[],'political_power','mesopotamia_egypt',NULL,'أنماط المركزية تغيرت عبر القرون؛ لا تعمم مرحلة واحدة على ألفي عام.','تعددت مدن سومر ثم ظهرت ممالك وإمبراطوريات إقليمية.','تبلورت ملكية مركزية مبكرة مع مراحل توحيد وانقسام وإعادة توحيد.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('me_society',ARRAY[],'society','mesopotamia_egypt',NULL,'العمل في المشروعات الكبرى تنوع بين التزامات وعمالة حرفية وموسمية.','حرف ومدن وتبادل بري وخليجي ورافدي وفئات مهنية متنوعة.','زراعة نيلية وحرف ومشروعات ملكية وتبادل مع النوبة وبلاد الشام.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('mi_economy',ARRAY[],'economy','maya_inca',NULL,'الجزية وإعادة التوزيع والعمل العام ترتيبات مختلفة؛ يجب فحصها في سياق كل إقليم.','اقتصادات زراعية وتجارية اعتمدت على الذرة والكاكاو والسبج والجزية والتبادل بين المدن.','إنتاج زراعي متنوع ومدرجات وتخزين وإعادة توزيع وعمل إلزامي/عام ضمن نظام الدولة.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('mi_environment',ARRAY[],'environment','maya_inca',NULL,'التنوع البيئي يفسر اختلاف استراتيجيات الزراعة والنقل، لكنه لا يحدد شكل النظام السياسي وحده.','بيئات استوائية وغابات ومرتفعات وأراضٍ كلسية ومصادر مياه موسمية.','جبال الأنديز بتدرج ارتفاعي ومناخات دقيقة ومدرجات وطرق جبلية.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('mi_evidence',ARRAY[],'evidence','maya_inca',NULL,'الاستعمار غيّر الأرشيف المادي والكتابي؛ افصل الرواية عن الدليل.','نقوش ومخطوطات وأدلة أثرية وقراءة لغوية حديثة.','آثار وكيبو وروايات استعمارية وشهادات محلية لاحقة.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('mi_institutions',ARRAY[],'institutions','maya_inca',NULL,'لا توجد دولة واحدة تمثل جميع مراحل المايا؛ كما اختلفت قدرة الإنكا على إدارة الأقاليم.','تحالفات وحروب ودبلوماسية وإدارة مدينية متفاوتة بين ممالك المايا.','شبكة طرق ومراكز إدارية ومحطات ومخازن ونظام عمل عام مرتبط بالدولة.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('mi_knowledge',ARRAY[],'knowledge','maya_inca',NULL,'لا تساوِ بين أنظمة الكتابة والتسجيل المختلفة، ولا تستنتج غياب المعرفة من اختلاف وسيطها.','كتابة هيروغليفية ونقوش وتقويمات وحساب ورصد فلكي موثق في آثار ونصوص.','كيبو للتسجيل الكمي والإداري ومعارف هندسية وزراعية وفلكية؛ تفسير وظائف الكيبو يتوسع بحثيًا.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('mi_networks',ARRAY[],'networks','maya_inca',NULL,'قارن كثافة الاتصال ووظائف الطرق ضمن اتساع الإقليم والبنية السياسية.','طرق إقليمية وتبادل بين المدن والمناطق الساحلية والمرتفعات.','شبكة طرق إمبراطورية تربط كوسكو بالأقاليم ومراكز التخزين والإدارة.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('mi_political',ARRAY[],'political_power','maya_inca',NULL,'مقارنة شبكة مدن بدولة إمبراطورية تتطلب الحذر من عدم التكافؤ.','شبكة مدن وممالك متنافسة ومتحالفة، لكل منها سلالات ومراكز طقسية وإدارة محلية.','دولة توسعية مركزها كوسكو ضمت أقاليم وشعوبًا متعددة عبر إدارة متفاوتة.') on conflict do nothing;
insert into public.history_comparison_observations (id,source_ids,dimension_id,comparison_id,evidence_note,comparative_reading,civilization_a_observation,civilization_b_observation) values ('mi_society',ARRAY[],'society','maya_inca',NULL,'المصطلحات الاجتماعية ليست متطابقة، ولا يمكن نقل فئات مجتمع إلى الآخر دون تعريف.','نخب حاكمة وكهنة وحرفيون ومزارعون وتفاوتات بين المدن والمناطق.','جماعات محلية وأسر ممتدة ونخب إدارية وعسكرية وشبكات التزامات جماعية.') on conflict do nothing;
